/h2><button class=\"modal-close-btn\">×</button></div><div class=\"modal-body\"><div class=\"status-list-viewport\"><div id=\"character-track\" class=\"character-track\"></div></div><div class=\"pagination-controls\"><button id=\"prev-page-btn\" class=\"page-nav-btn\">上一页</button><button id=\"next-page-btn\" class=\"page-nav-btn\">下一页</button></div></div></div>\n    </div>\n</div>\n<textarea id=\"game-data-source\" style=\"display:none;\">$1</textarea>\n\n<script>\nconst ASSETS = {\n    characters: {},\n    backgrounds: {},\n    bgm: {}\n};\n/**\n * Resolves a keyword or raw URL to a full URL.\n * If the value is already a URL (starts with http), return as-is.\n * Otherwise look it up in the ASSETS table.\n */\nfunction normalizeAssetKey(key) {\n    return String(key || '').toLowerCase().replace(/[^a-z0-9]+/g, '');\n}\n\nfunction pickRandomAssetUrl(value) {\n    if (Array.isArray(value)) {\n        const filtered = value.filter(Boolean);\n        if (filtered.length === 0) return null;\n        return filtered[Math.floor(Math.random() * filtered.length)];\n    }\n    return value || null;\n}\n\nconst CHARACTER_FALLBACK_DEFAULTS = {};\n\nfunction resolveCharacterSprite(key) {\n    if (!key) return null;\n    const trimmed = String(key).trim();\n    if (!trimmed) return null;\n    if (trimmed.startsWith('http')) return trimmed;\n\n    if (ASSETS.characters[trimmed]) return ASSETS.characters[trimmed];\n\n    const normalized = normalizeAssetKey(trimmed);\n    if (ASSETS.characters[normalized]) return ASSETS.characters[normalized];\n\n    for (const [needle, fallbackKey] of Object.entries(CHARACTER_FALLBACK_DEFAULTS)) {\n        if (normalized.includes(needle)) {\n            return ASSETS.characters[fallbackKey] || null;\n        }\n    }\n    return null;\n}\n\n/**\n * Resolves a keyword or raw URL to a full URL.\n * If the value is already a URL (starts with http), return as-is.\n * Otherwise look it up in the ASSETS table.\n */\nfunction resolveAsset(table, key) {\n    if (!key) return null;\n    const trimmed = String(key).trim();\n    if (!trimmed) return null;\n    if (trimmed.startsWith('http')) return trimmed;\n    if (table === 'characters') return resolveCharacterSprite(trimmed);\n\n    const tableValue = ASSETS[table] ? ASSETS[table][trimmed] : undefined;\n    if (Array.isArray(tableValue)) return pickRandomAssetUrl(tableValue);\n    return tableValue || trimmed;\n}\n\n</script>\n\n<script>\nfunction parseGameData(text) {\n    const scenesData = text.trim().split(/\\n---\\n/);\n    const scenes = [];\n    let lastValidSceneData = {};\n\n    scenesData.forEach(sceneText => {\n        if (!sceneText.trim()) return;\n        const lines = sceneText.trim().split('\\n');\n        const scene = {\n            id: scenes.length, dialogues: [], choices: [], characters: [],\n            audio: {}, is_cg_mode: false, cg_image: null,\n        };\n        let inPhoneBlock = false, inCgBlock = false, isParsingMemo = false;\n        let currentPhoneData = null, currentContact = null;\n\n        for (const line of lines) {\n            const trimmedLine = line.trim();\n            if (trimmedLine === '[CG]') { inCgBlock = true; scene.is_cg_mode = true; continue; }\n            if (trimmedLine === '[/CG]') { inCgBlock = false; continue; }\n            if (trimmedLine === '[PHONE]') {\n                inPhoneBlock = true; currentPhoneData = { memos: '', contacts: [] }; continue;\n            }\n            if (trimmedLine === '[/PHONE]') {\n                inPhoneBlock = false;\n                if (currentPhoneData) {\n                    scene.dialogues.push({ type: 'action', command: 'SHOW_PHONE', phone_data: currentPhoneData, id: `s${scene.id}-act${scene.dialogues.length}` });\n                    currentPhoneData = null;\n                }\n                continue;\n            }\n\n            if (inPhoneBlock) {\n                if (trimmedLine.startsWith('@memo:')) {\n                    isParsingMemo = true; currentPhoneData.memos = '';\n                    const memoTitle = trimmedLine.substring(6).trim();\n                    if (memoTitle) currentPhoneData.memos += memoTitle + '\\n';\n                    continue;\n                }\n                if (trimmedLine.startsWith('@contact:')) {\n                    isParsingMemo = false;\n                    const [name, avatar] = trimmedLine.substring(9).split(',').map(s => s.trim());\n                    currentContact = { name, avatar, messages: [] };\n                    currentPhoneData.contacts.push(currentContact);\n                    continue;\n                }\n                if (isParsingMemo) {\n                    currentPhoneData.memos += (currentPhoneData.memos ? '\\n' : '') + trimmedLine; continue;\n                }\n                if (trimmedLine.startsWith('R:') && currentContact) { currentContact.messages.push({ type: 'received', text: trimmedLine.substring(2).trim() }); continue; }\n                if (trimmedLine.startsWith('S:') && currentContact) { currentContact.messages.push({ type: 'sent', text: trimmedLine.substring(2).trim() }); continue; }\n                continue;\n            }\n\n            if (trimmedLine.startsWith('@bg:')) { scene.bg_image = resolveAsset('backgrounds', trimmedLine.substring(4).trim()); continue; }\n            if (trimmedLine.startsWith('@cg_image:')) { scene.cg_image = trimmedLine.substring(10).trim(); continue; }\n            if (trimmedLine.startsWith('@location:')) { scene.status_location = trimmedLine.substring(10).trim(); continue; }\n            if (trimmedLine.startsWith('@time:')) { scene.status_time = trimmedLine.substring(6).trim(); continue; }\n            if (trimmedLine.startsWith('@bgm:')) { scene.audio.bgm = trimmedLine.substring(5).trim(); continue; }\n            if (trimmedLine.startsWith('* ')) {\n                const [label, action] = trimmedLine.substring(2).split('->').map(s => s.trim());\n                scene.choices.push({ label, action }); continue;\n            }\n            if (trimmedLine.startsWith('@input:')) { scene.custom_input_placeholder = trimmedLine.substring(7).trim(); continue; }\n            if (trimmedLine.startsWith('@status:')) {\n                const [name, affection, avatarRaw] = trimmedLine.substring(8).split(',').map(s => s.trim());\n                const avatar = resolveAsset('characters', avatarRaw);\n                scene.characters.push({ name, affection: parseInt(affection), avatar }); continue;\n            }\n\n            const dialogueMatch = trimmedLine.match(/^([^>]+)>\\s*(.*)/);\n            if (dialogueMatch) {\n                let speaker = dialogueMatch[1].trim();\n                const text = dialogueMatch[2].trim();\n                let spriteInfo = null;\n\n                if (speaker.toLowerCase() !== '旁白') {\n                    const spriteMatch = speaker.match(/^(.*?)\\(([^)]*)\\)$/);\n                    if (spriteMatch && !inCgBlock) {\n                        speaker = spriteMatch[1].trim();\n                        const params = spriteMatch[2].split(',').map(p => p.trim());\n                        spriteInfo = {\n                            url: resolveAsset('characters', params[0]) || null,\n                            position: params[1] || 'center',\n                            status: params[2] || 'silent',\n                            scale: parseFloat(params[3]) || 1.0\n                        };\n                    }\n                }\n                scene.dialogues.push({\n                    type: 'dialogue', speaker: speaker, text: text, sprite: spriteInfo,\n                    is_narrator: speaker.toLowerCase() === '旁白', id: `s${scene.id}-d${scene.dialogues.length}`\n                });\n                continue;\n            }\n        }\n\n        scene.bg_image = scene.bg_image !== undefined ? scene.bg_image : lastValidSceneData.bg_image;\n        scene.cg_image = scene.cg_image !== undefined ? scene.cg_image : lastValidSceneData.cg_image;\n        scene.is_cg_mode = scene.is_cg_mode !== undefined ? scene.is_cg_mode : lastValidSceneData.is_cg_mode;\n        scene.status_location = scene.status_location || lastValidSceneData.status_location;\n        scene.status_time = scene.status_time || lastValidSceneData.status_time;\n        if (scene.characters.length === 0 && lastValidSceneData.characters) {\n            scene.characters = lastValidSceneData.characters;\n        }\n        scenes.push(scene);\n        lastValidSceneData = JSON.parse(JSON.stringify(scene));\n    });\n    return { scenes, audio: { sfx: { click: \"https://s3plus.meituan.net/opapisdk/op_ticket_1_885190757_1780574421593_gwWljbcb.m4a\", confirm: \"https://files.catbox.moe/agwxnc.mp3\" } } };\n}\n\ndocument.addEventListener('DOMContentLoaded', async () => {\n    const dataEl = document.getElementById('game-data-source');\n    if (!dataEl || !dataEl.textContent) { console.error('Game data not found!'); return; }\n    const gameData = parseGameData(dataEl.textContent);\n\n    const scenes = gameData.scenes;\n    if (!scenes || scenes.length === 0) { console.error('No scenes parsed!'); return; }\n    let currentSceneIndex = 0, currentDialogueIndex = 0;\n    let dialogueSegments = [], currentSegmentIndex = 0;\n\n    const bgmPlayer = document.getElementById('bgm-player');\n    const sfxPlayer = document.getElementById('sfx-player');\n    let currentBgmUrl = '';\n\n    const root = document.documentElement;\n    const settingsTabs = document.querySelectorAll('.settings-tab-btn');\n    const settingsPages = document.querySelectorAll('.settings-page');\n    // Audio\n    const bgmSlider = document.getElementById('bgm-slider');\n    const sfxSlider = document.getElementById('sfx-slider');\n    // Display\n    const fontSizeInput = document.getElementById('font-size-input');\n    const uiScaleSlider = document.getElementById('ui-scale-slider');\n    const panelScaleSlider = document.getElementById('panel-scale-slider');\n    const hideUiToggle = document.getElementById('hide-ui-toggle');\n    const hideStatusInfoToggle = document.getElementById('hide-status-info-toggle');\n    // Sprite\n    const spriteScaleSlider = document.getElementById('sprite-scale-slider');\n    const spriteOffsetLeftSlider = document.getElementById('sprite-offset-left-slider');\n    const spriteOffsetCenterSlider = document.getElementById('sprite-offset-center-slider');\n    const spriteOffsetRightSlider = document.getElementById('sprite-offset-right-slider');\n    const backgroundPositionSlider = document.getElementById('background-position-slider');\n    // Theme\n    const themeResetBtn = document.getElementById('theme-reset-btn');\n    const themeSliderTrack = document.getElementById('theme-slider-track');\n    const themePrevBtn = document.getElementById('theme-prev-btn');\n    const themeNextBtn = document.getElementById('theme-next-btn');\n    let themeCurrentPage = 0;\n    let totalThemePages = 0;\n\n    const statusInfoPanel = document.getElementById('status-info-panel');\n    const bgmToggleBtn = document.getElementById('bgm-toggle-btn');\n    const bgmToggleIcon = document.getElementById('bgm-toggle-icon');\n    const fullscreenIcon = document.getElementById('fullscreen-icon');\n    const phoneBtn = document.getElementById('phone-btn');\n    const historyBtn = document.getElementById('history-btn');\n    const statusBtn = document.getElementById('status-btn');\n    const settingsBtn = document.getElementById('settings-btn');\n    const dialogueBox = document.getElementById('dialogue-box');\n    const textContentEl = document.getElementById('text-content');\n\n    function updateBgmButton() {\n        if (!bgmToggleBtn || !bgmToggleIcon) return;\n        const isPlaying = !bgmPlayer.paused && !bgmPlayer.ended;\n        bgmToggleBtn.title = isPlaying ? '暂停BGM' : '播放BGM';\n        const label = isPlaying ? '暂停BGM' : '播放BGM';\n        if (bgmToggleIcon instanceof HTMLImageElement) { bgmToggleIcon.alt = label; }\n        else { bgmToggleIcon.textContent = isPlaying ? 'Ⅱ' : '▶'; bgmToggleIcon.setAttribute('aria-label', label); }\n    }\n\n    bgmPlayer.addEventListener('play', updateBgmButton);\n    bgmPlayer.addEventListener('pause', updateBgmButton);\n\n    const audioManager = {\n        tabId: Date.now(), isMaster: false, channel: new BroadcastChannel('bgm_audio_channel'), storageKey: 'bgmMasterTab',\n        init() {\n            this.channel.onmessage = this.handleMessage.bind(this);\n            window.addEventListener('beforeunload', this.handleUnload.bind(this));\n            window.addEventListener('storage', this.handleStorageChange.bind(this));\n            this.claimMaster();\n        },\n        handleMessage(event) {\n            if (event.data.type === 'CLAIM_MASTER' && event.data.tabId > this.tabId) {\n                if (this.isMaster) { console.log(`Tab ${this.tabId}: Relinquishing master status to ${event.data.tabId}`); this.isMaster = false; bgmPlayer.pause(); }\n            }\n        },\n        claimMaster() {\n            const currentMaster = localStorage.getItem(this.storageKey);\n            if (!currentMaster || parseInt(currentMaster) < this.tabId) {\n                console.log(`Tab ${this.tabId}: Claiming master status.`);\n                this.isMaster = true; localStorage.setItem(this.storageKey, this.tabId);\n                this.channel.postMessage({ type: 'CLAIM_MASTER', tabId: this.tabId });\n                if (!bgmPlayer.paused) { bgmPlayer.play(); } else if (currentBgmUrl) { changeBgm(currentBgmUrl); }\n            } else { this.isMaster = false; }\n        },\n        handleUnload() { if (this.isMaster) { localStorage.removeItem(this.storageKey); } },\n        handleStorageChange(e) { if (e.key === this.storageKey && e.newValue === null) { setTimeout(() => this.claimMaster(), 50 + Math.random() * 100); } }\n    };\n\n    const settingsManager = {\n        key: 'pixelGameSettings_v4',\n        defaults: {\n            bgmVolume: 0.5, sfxVolume: 0.8, fontSize: 20, uiScale: 1.0, panelScale: 1.0,\n            hideUi: false, hideStatusInfo: false, globalSpriteScale: 1.0, spriteOffsetLeft: -10,\n            spriteOffsetCenter: -50, spriteOffsetRight: -10, backgroundPositionX: 50,\n            // Theme Defaults\n            dialogueBgHex: '#000000', dialogueBgAlpha: 0.80, mainTextColor: '#ffffff',\n            nameTagBg: '#000000', nameTagText: '#d1a400', narratorTagBg: '#666666',\n            mainBorderColor: '#000000', mainShadowColor: 'transparent', choiceBtnBg: '#ffffff',\n            choiceBtnText: '#000000', choiceBtnBorder: '#000000', btnShadowColor: '#000000',\n            windowBgColor: '#ffffff', modalBgColor: '#ffffff', modalHeaderText: '#000000',\n            modalBodyText: '#000000'\n        },\n        settings: {},\n        themeConfig: [\n            { key: 'dialogueBg', label: '对话框背景', type: 'rgba', hexKey: 'dialogueBgHex', alphaKey: 'dialogueBgAlpha', cssVar: '--dialogue-bg' },\n            { key: 'mainTextColor', label: '主要文本', type: 'color', cssVar: '--main-text-color' },\n            { key: 'nameTagBg', label: '名称标签背景', type: 'color', cssVar: '--name-tag-bg' },\n            { key: 'nameTagText', label: '名称标签文本', type: 'color', cssVar: '--name-tag-text' },\n            { key: 'narratorTagBg', label: '旁白标签背景', type: 'color', cssVar: '--narrator-tag-bg' },\n            { key: 'mainBorderColor', label: '主要边框', type: 'color', cssVar: '--main-border-color' },\n            { key: 'mainShadowColor', label: '窗口阴影', type: 'color', cssVar: '--main-shadow-color' },\n            { key: 'choiceBtnBg', label: '选项按钮背景', type: 'color', cssVar: '--choice-btn-bg' },\n            { key: 'choiceBtnText', label: '选项按钮文本', type: 'color', cssVar: '--choice-btn-text' },\n            { key: 'choiceBtnBorder', label: '选项按钮边框', type: 'color', cssVar: '--choice-btn-border' },\n            { key: 'btnShadowColor', label: '按钮阴影', type: 'color', cssVar: '--btn-shadow-color' },\n            { key: 'windowBgColor', label: '窗口背景', type: 'color', cssVar: '--window-bg-color' },\n            { key: 'modalBgColor', label: '弹窗背景', type: 'color', cssVar: '--modal-bg-color' },\n            { key: 'modalHeaderText', label: '弹窗标题文本', type: 'color', cssVar: '--modal-header-text' },\n            { key: 'modalBodyText', label: '弹窗正文文本', type: 'color', cssVar: '--modal-body-text' },\n        ],\n        hexToRgba(hex, alpha) {\n            const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);\n            return `rgba(${r}, ${g}, ${b}, ${alpha})`;\n        },\n        load() {\n            try {\n                const storedSettings = JSON.parse(localStorage.getItem(this.key));\n                this.settings = { ...this.defaults, ...storedSettings };\n            } catch (e) { this.settings = { ...this.defaults }; }\n            this.settings.mainShadowColor = 'transparent';\n            this.buildThemeUI(); this.applyAll();\n        },\n        save() { localStorage.setItem(this.key, JSON.stringify(this.settings)); },\n        update(key, value) { this.settings[key] = value; this.apply(key, value); this.save(); },\n        apply(key, value) {\n            switch (key) {\n                case 'bgmVolume': bgmPlayer.volume = value; bgmSlider.value = value * 100; break;\n                case 'sfxVolume': sfxSlider.value = value * 100; break;\n                case 'fontSize': root.style.setProperty('--dialogue-font-size-em', `${value / 16}em`); fontSizeInput.value = value; break;\n                case 'uiScale': root.style.setProperty('--ui-scale', value); uiScaleSlider.value = value * 100; break;\n                case 'panelScale': root.style.setProperty('--panel-scale', value); panelScaleSlider.value = value * 100; break;\n                case 'hideUi':\n                    [phoneBtn, historyBtn, statusBtn].forEach(el => el.classList.toggle('ui-hidden', value));\n                    statusInfoPanel.classList.toggle('ui-hidden', value || this.settings.hideStatusInfo);\n                    hideUiToggle.checked = value; break;\n                case 'hideStatusInfo': statusInfoPanel.classList.toggle('ui-hidden', value || this.settings.hideUi); hideStatusInfoToggle.checked = value; break;\n                case 'globalSpriteScale': root.style.setProperty('--global-sprite-scale', value); spriteScaleSlider.value = value * 100; break;\n                case 'spriteOffsetLeft': root.style.setProperty('--sprite-offset-left', `${value}%`); spriteOffsetLeftSlider.value = value; break;\n                case 'spriteOffsetCenter': root.style.setProperty('--sprite-offset-center', `${value}%`); spriteOffsetCenterSlider.value = value; break;\n                case 'spriteOffsetRight': root.style.setProperty('--sprite-offset-right', `${value}%`); spriteOffsetRightSlider.value = value; break;\n                case 'backgroundPositionX': root.style.setProperty('--background-position-x', `${value}%`); backgroundPositionSlider.value = value; break;\n                default:\n                    const themeItem = this.themeConfig.find(t => t.key === key || t.hexKey === key || t.alphaKey === key);\n                    if (themeItem) {\n                        if (themeItem.type === 'rgba') {\n                            root.style.setProperty(themeItem.cssVar, this.hexToRgba(this.settings[themeItem.hexKey], this.settings[themeItem.alphaKey]));\n                            const hexInput = document.getElementById(`theme-${themeItem.hexKey}`); if(hexInput) hexInput.value = this.settings[themeItem.hexKey];\n                            const alphaInput = document.getElementById(`theme-${themeItem.alphaKey}`); if(alphaInput) alphaInput.value = this.settings[themeItem.alphaKey] * 100;\n                        } else {\n                            root.style.setProperty(themeItem.cssVar, value);\n                            const colorInput = document.getElementById(`theme-${themeItem.key}`); if(colorInput) colorInput.value = value;\n                        }\n                    }\n            }\n        },\n        applyAll() { Object.keys(this.settings).forEach(key => this.apply(key, this.settings[key])); },\n        buildThemeUI() {\n            themeSliderTrack.innerHTML = ''; let pageHTML = '';\n            this.themeConfig.forEach((item, index) => {\n                if (index % 4 === 0) { pageHTML = `<div class=\"theme-slider-page\">`; }\n                let inputHTML = '';\n                if (item.type === 'rgba') {\n                    inputHTML = `<input id=\"theme-${item.hexKey}\" type=\"color\"><input id=\"theme-${item.alphaKey}\" type=\"range\" min=\"0\" max=\"100\">`;\n                } else {\n                    inputHTML = `<input id=\"theme-${item.key}\" type=\"color\">`;\n                }\n                pageHTML += `<div class=\"settings-item\"><label>${item.label}</label>${inputHTML}</div>`;\n                if ((index + 1) % 4 === 0 || index === this.themeConfig.length - 1) {\n                    pageHTML += `</div>`; themeSliderTrack.innerHTML += pageHTML;\n                }\n            });\n            totalThemePages = themeSliderTrack.children.length;\n            this.themeConfig.forEach(item => {\n                if (item.type === 'rgba') {\n                    document.getElementById(`theme-${item.hexKey}`).addEventListener('input', e => this.update(item.hexKey, e.target.value));\n                    document.getElementById(`theme-${item.alphaKey}`).addEventListener('input', e => this.update(item.alphaKey, e.target.value / 100));\n                } else {\n                    document.getElementById(`theme-${item.key}`).addEventListener('input', e => this.update(item.key, e.target.value));\n                }\n            });\n        },\n        resetTheme() {\n            this.themeConfig.forEach(item => {\n                if (item.type === 'rgba') {\n                    this.settings[item.hexKey] = this.defaults[item.hexKey];\n                    this.settings[item.alphaKey] = this.defaults[item.alphaKey];\n                } else {\n                    this.settings[item.key] = this.defaults[item.key];\n                }\n            });\n            this.applyAll(); this.save();\n        }\n    };\n\n    window.playSfx = (soundName) => {\n        const sfxUrl = gameData.audio?.sfx?.[soundName];\n        if (!sfxUrl) return;\n        sfxPlayer.src = sfxUrl; sfxPlayer.volume = settingsManager.settings.sfxVolume; sfxPlayer.play();\n    };\n    function changeBgm(newBgmUrlOrKey) {\n        const resolvedBgmUrl = resolveAsset('bgm', newBgmUrlOrKey);\n        if (!audioManager.isMaster) { currentBgmUrl = resolvedBgmUrl || ''; bgmPlayer.pause(); updateBgmButton(); return; }\n        if (currentBgmUrl === resolvedBgmUrl && !bgmPlayer.paused) return;\n        currentBgmUrl = resolvedBgmUrl;\n        if (resolvedBgmUrl) {\n            bgmPlayer.src = resolvedBgmUrl; bgmPlayer.volume = settingsManager.settings.bgmVolume;\n            bgmPlayer.play().catch(() => { document.body.addEventListener('click', () => { if(audioManager.isMaster) bgmPlayer.play(); }, { once: true }); });\n        } else { bgmPlayer.pause(); bgmPlayer.src = ''; }\n        updateBgmButton();\n    }\n\n\n    settingsTabs.forEach(tab => {\n        tab.addEventListener('click', () => {\n            settingsTabs.forEach(t => t.classList.remove('active'));\n            settingsPages.forEach(p => p.classList.remove('active'));\n            tab.classList.add('active');\n            document.getElementById(tab.dataset.target).classList.add('active');\n        });\n    });\n    // Listeners\n    bgmSlider.addEventListener('input', (e) => settingsManager.update('bgmVolume', e.target.value / 100));\n    updateBgmButton();\n    sfxSlider.addEventListener('input', (e) => settingsManager.update('sfxVolume', e.target.value / 100));\n    fontSizeInput.addEventListener('change', (e) => settingsManager.update('fontSize', parseInt(e.target.value)));\n    uiScaleSlider.addEventListener('input', (e) => settingsManager.update('uiScale', e.target.value / 100));\n    panelScaleSlider.addEventListener('input', (e) => settingsManager.update('panelScale', e.target.value / 100));\n    hideUiToggle.addEventListener('change', (e) => settingsManager.update('hideUi', e.target.checked));\n    hideStatusInfoToggle.addEventListener('change', (e) => settingsManager.update('hideStatusInfo', e.target.checked));\n    spriteScaleSlider.addEventListener('input', (e) => settingsManager.update('globalSpriteScale', e.target.value / 100));\n    spriteOffsetLeftSlider.addEventListener('input', (e) => settingsManager.update('spriteOffsetLeft', parseInt(e.target.value)));\n    spriteOffsetCenterSlider.addEventListener('input', (e) => settingsManager.update('spriteOffsetCenter', parseInt(e.target.value)));\n    spriteOffsetRightSlider.addEventListener('input', (e) => settingsManager.update('spriteOffsetRight', parseInt(e.target.value)));\n    backgroundPositionSlider.addEventListener('input', (e) => settingsManager.update('backgroundPositionX', parseInt(e.target.value)));\n    themeResetBtn.addEventListener('click', () => settingsManager.resetTheme());\n    themePrevBtn.addEventListener('click', () => { if (themeCurrentPage > 0) { themeCurrentPage--; themeSliderTrack.style.transform = `translateX(-${themeCurrentPage * 100}%)`; } });\n    themeNextBtn.addEventListener('click', () => { if (themeCurrentPage < totalThemePages - 1) { themeCurrentPage++; themeSliderTrack.style.transform = `translateX(-${themeCurrentPage * 100}%)`; } });\n\n    // CG Viewer Logic\n    const cgDisplayArea = document.getElementById('cg-display-area');\n    const cgDisplay = document.getElementById('cg-image-display');\n    const cgCounter = document.getElementById('cg-counter');\n    const cgPrevBtn = document.getElementById('cg-prev-btn');\n    const cgNextBtn = document.getElementById('cg-next-btn');\n    let currentCgIndex = 0;\n\n    function showCg(index) {\n        if (!CG_GALLERY_IMAGES || CG_GALLERY_IMAGES.length === 0) {\n            cgDisplay.src = ''; cgCounter.textContent = '无CG';\n            cgPrevBtn.style.visibility = 'hidden'; cgNextBtn.style.visibility = 'hidden';\n            cgDisplayArea.style.aspectRatio = '16 / 9'; // 重置为默认比例\n            return;\n        }\n        currentCgIndex = (index + CG_GALLERY_IMAGES.length) % CG_GALLERY_IMAGES.length;\n        cgDisplay.src = CG_GALLERY_IMAGES[currentCgIndex];\n        cgCounter.textContent = `${currentCgIndex + 1} / ${CG_GALLERY_IMAGES.length}`;\n        cgPrevBtn.style.visibility = 'visible'; cgNextBtn.style.visibility = 'visible';\n    }\n\n    // 新增: 图片加载成功后调整容器比例\n    cgDisplay.onload = () => {\n        const { naturalWidth, naturalHeight } = cgDisplay;\n        if (naturalHeight > 0) {\n            cgDisplayArea.style.aspectRatio = `${naturalWidth} / ${naturalHeight}`;\n        }\n    };\n    // 新增: 图片加载失败后重置容器比例\n    cgDisplay.onerror = () => {\n        cgDisplayArea.style.aspectRatio = '16 / 9';\n        cgDisplay.src = ''; // 清除损坏的图片\n        cgCounter.textContent = `图片加载失败`;\n    };\n\n    cgPrevBtn.addEventListener('click', () => showCg(currentCgIndex - 1));\n    cgNextBtn.addEventListener('click', () => showCg(currentCgIndex + 1));\n    document.querySelector('.settings-tab-btn[data-target=\"settings-page-cg\"]').addEventListener('click', () => showCg(0));\n\n\n    const bgImage = document.getElementById('bg-image'), bgImageNext = document.getElementById('bg-image-next');\n    const cgLayer = document.getElementById('cg-layer');\n    const statusLocation = document.getElementById('status-location'), statusTime = document.getElementById('status-time');\n    const nameTag = document.getElementById('name-tag');\n\n    function updateStatusInfoPanel() {\n        const locationText = (statusLocation.textContent || '').trim();\n        const timeText = (statusTime.textContent || '').trim();\n        const hasInfo = Boolean(locationText || timeText);\n        statusInfoPanel.classList.toggle('is-empty', !hasInfo);\n        statusInfoPanel.style.display = hasInfo ? 'flex' : 'none';\n    }\n    const continueBtn = document.getElementById('dialogue-continue'), choicesArea = document.getElementById('choices-area');\n    const backBtn = document.getElementById('dialogue-back');\n    let dialogueHistory = []; // stack: [{sceneIndex, dialogueIndex, segmentIndex}]\n    let isGoingBack = false;\n    let choiceReturnState = null;\n    const spriteSlots = { left: document.getElementById('sprite-slot-left'), center: document.getElementById('sprite-slot-center'), right: document.getElementById('sprite-slot-right') };\n    let readDialogueHistory = new Set();\n    let activeSprites = { left: null, center: null, right: null };\n\n    function clearSprite(position) {\n        if (activeSprites[position]) {\n            const spriteToRemove = activeSprites[position];\n            spriteToRemove.classList.add('fade-out');\n            setTimeout(() => { if (spriteToRemove.parentElement) spriteToRemove.parentElement.removeChild(spriteToRemove); }, 400);\n            activeSprites[position] = null;\n        }\n    }\n    function renderSpriteForDialogue(dialogue) {\n        const spriteInfo = dialogue.sprite;\n        if (dialogue.is_narrator || !spriteInfo || !spriteInfo.url) {\n            Object.values(activeSprites).forEach(sprite => { if (sprite) { sprite.classList.remove('speaking'); sprite.classList.add('silent'); }});\n            return;\n        }\n        const { url, position, status, scale } = spriteInfo;\n        if (position === 'center') { clearSprite('left'); clearSprite('right'); }\n        else if (position === 'left' || position === 'right') { clearSprite('center'); }\n        Object.keys(activeSprites).forEach(pos => { if (pos !== position && activeSprites[pos]) { activeSprites[pos].classList.remove('speaking'); activeSprites[pos].classList.add('silent'); }});\n        const slot = spriteSlots[position]; if (!slot) return;\n        const existingSprite = activeSprites[position];\n\n        if (existingSprite && existingSprite.src.includes(new URL(url, location.href).pathname)) {\n            existingSprite.classList.remove('speaking', 'silent');\n            existingSprite.classList.add(status);\n            existingSprite.style.setProperty('--individual-sprite-scale', scale);\n        } else {\n            clearSprite(position);\n            const spriteImg = document.createElement('img');\n            spriteImg.src = url; spriteImg.className = 'character-sprite'; spriteImg.classList.add(status);\n            spriteImg.style.setProperty('--individual-sprite-scale', scale); spriteImg.style.opacity = '0';\n            slot.appendChild(spriteImg);\n            requestAnimationFrame(() => { spriteImg.style.opacity = '1'; });\n            activeSprites[position] = spriteImg;\n        }\n    }\n    const phoneUI = document.getElementById('phone-ui');\n    const phoneHomeBtn = document.getElementById('phone-home-btn');\n    const phoneViews = document.querySelectorAll('.phone-view');\n    const appIcons = document.querySelectorAll('.app-icon');\n    const backButtons = document.querySelectorAll('.back-button');\n    const memoContent = document.getElementById('memo-view-content');\n    const contactsList = document.getElementById('contacts-list');\n    const chatViewName = document.getElementById('chat-with-name');\n    const chatContentArea = document.getElementById('chat-view-content');\n\n    function showPhoneView(viewId) { phoneViews.forEach(view => view.classList.toggle('active', view.id === viewId)); }\n    function renderPhoneData(phoneData) {\n        if (!phoneData) return;\n        memoContent.textContent = phoneData.memos || '没有备忘录内容。';\n        contactsList.innerHTML = '';\n        contactsList.style.color = '#000';\n        if (phoneData.contacts && Array.isArray(phoneData.contacts)) {\n            phoneData.contacts.forEach(contact => {\n                const item = document.createElement('div');\n                item.className = 'contact-item';\n                item.innerHTML = `<div class=\"contact-avatar\"><img src=\"${contact.avatar || ''}\" alt=\"${contact.name}\"></div><span class=\"contact-name\">${contact.name}</span>`;\n                item.addEventListener('click', () => {\n                    playSfx('click'); chatViewName.textContent = contact.name; chatContentArea.innerHTML = '';\n                    if(contact.messages && Array.isArray(contact.messages)){\n                        contact.messages.forEach(msg => {\n                            const bubble = document.createElement('div');\n                            bubble.className = `chat-bubble ${msg.type}`; bubble.textContent = msg.text;\n                            chatContentArea.appendChild(bubble);\n                        });\n                    }\n                    showPhoneView('chat-view');\n                });\n                contactsList.appendChild(item);\n            });\n        }\n    }\n    function closePhone() { playSfx('click'); phoneUI.classList.remove('active'); dialogueBox.classList.remove('hidden'); }\n    phoneHomeBtn.addEventListener('click', closePhone);\n    phoneBtn.addEventListener('click', () => {\n        playSfx('click'); phoneUI.classList.toggle('active');\n        dialogueBox.classList.toggle('hidden', phoneUI.classList.contains('active'));\n        if(phoneUI.classList.contains('active')) showPhoneView('home-view');\n    });\n    appIcons.forEach(icon => icon.addEventListener('click', () => { playSfx('click'); showPhoneView(icon.dataset.target); }));\n    backButtons.forEach(button => button.addEventListener('click', () => { playSfx('click'); showPhoneView(button.dataset.target); }));\n\n    function transitionToScene(sceneIndex, isInitial = false) {\n        const scene = scenes[sceneIndex]; if (!scene) return;\n        currentSceneIndex = sceneIndex;\n        if (scene.bg_image && (isInitial || bgImage.style.backgroundImage.indexOf(scene.bg_image) === -1)) {\n   